ALTER TABLE controls.change_proposals DROP CONSTRAINT change_proposals_kind_check;
ALTER TABLE controls.change_proposals ADD CONSTRAINT change_proposals_kind_check CHECK(kind IN ('PRODUCT','TERMS','CORRECTION','MASTER_REFERENCE'));
CREATE TABLE data.master_refs(id uuid PRIMARY KEY,kind text NOT NULL,source text NOT NULL DEFAULT 'CORE',source_ref uuid NOT NULL,canonical_ref uuid NOT NULL,revision bigint NOT NULL DEFAULT 1,source_version bigint NOT NULL,origin_event uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(source,kind,source_ref));
CREATE TABLE data.account_views(account_id uuid PRIMARY KEY,party_id uuid NOT NULL,product_version_id uuid NOT NULL,state text NOT NULL,debit_blocked boolean NOT NULL,credit_blocked boolean NOT NULL,source_version bigint NOT NULL,source_as_of timestamptz NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE data.transaction_views(batch_id uuid NOT NULL,account_id uuid NOT NULL,operation_id uuid NOT NULL,document jsonb NOT NULL,origin_event uuid NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(batch_id,account_id));
CREATE TABLE data.hold_views(operation_id uuid PRIMARY KEY,account_id uuid NOT NULL,state text NOT NULL,submitted boolean NOT NULL,source_version bigint NOT NULL,source_as_of timestamptz NOT NULL);
CREATE TABLE data.master_history(id uuid PRIMARY KEY,reference_id uuid NOT NULL REFERENCES data.master_refs(id),previous_canonical uuid NOT NULL,new_canonical uuid NOT NULL,approval_id uuid NOT NULL UNIQUE,maker_person uuid NOT NULL,checker_person uuid NOT NULL,evidence_ref uuid NOT NULL,case_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(maker_person<>checker_person));
CREATE TABLE data.reference_conflicts(id uuid PRIMARY KEY,reference_id uuid NOT NULL REFERENCES data.master_refs(id),proposed_canonical uuid NOT NULL,evidence_ref uuid NOT NULL,state text NOT NULL DEFAULT 'REVIEW_REQUIRED',case_id uuid,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(reference_id,proposed_canonical,evidence_ref));
CREATE FUNCTION data.immutable_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Immutable data lineage'; END $$;
CREATE TRIGGER immutable_master_history BEFORE UPDATE OR DELETE OR TRUNCATE ON data.master_history FOR EACH STATEMENT EXECUTE FUNCTION data.immutable_history();
